#!/usr/bin/env bash
set -Eeuo pipefail
SESSION_START_EPOCH="$(date +%s)"
PACK_ID="PACK_D04U_DENSE"
REPO_URL="${DT1D_CNN_REPO_URL:-https://github.com/tydeptrai21042004/whc-dt1d.git}"
REPO_COMMIT="${DT1D_CNN_COMMIT:-}"
WORKDIR=/kaggle/working
REPO_DIR="$WORKDIR/whc-dt1d-$PACK_ID"
DATA_ROOT="$WORKDIR/data_$PACK_ID"
PROGRESS_BASE="$WORKDIR/packed_progress_$PACK_ID"
RESULT_ZIP="$WORKDIR/${PACK_ID}_results.zip"
SAFE_MINUTES=690
RESERVE_MINUTES=30
SAFETY_FACTOR=1.55
export SESSION_START_EPOCH PACK_ID REPO_DIR DATA_ROOT PROGRESS_BASE RESULT_ZIP SAFE_MINUTES RESERVE_MINUTES SAFETY_FACTOR
pack_results() {
  python - <<'PYZIP'
import os,zipfile
from pathlib import Path
r=Path(os.environ['PROGRESS_BASE']); d=Path(os.environ['RESULT_ZIP']); d.unlink(missing_ok=True)
with zipfile.ZipFile(d,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
    if r.exists():
        for p in r.rglob('*'):
            if p.is_file() and p.suffix.lower() not in {'.pth','.pt','.ckpt'}: z.write(p,p.relative_to(r.parent))
print('RESULT_ZIP=',d)
PYZIP
  ls -lh "$RESULT_ZIP" || true
}
trap 'rc=$?; trap - EXIT; pack_results || true; exit $rc' EXIT
rm -rf "$REPO_DIR"; for n in 1 2 3; do git clone --depth 1 "$REPO_URL" "$REPO_DIR" && break || sleep $((n*5)); done; [[ -d "$REPO_DIR/.git" ]] || exit 2
cd "$REPO_DIR"; if [[ -n "$REPO_COMMIT" ]]; then git fetch --depth 1 origin "$REPO_COMMIT"; git checkout --detach "$REPO_COMMIT"; fi; echo SOURCE_COMMIT=$(git rev-parse HEAD)
python -m pip install -q --upgrade-strategy only-if-needed -r requirements-kaggle.txt
python - <<'PYTOOLS'
import base64
from pathlib import Path
Path('/kaggle/working/dense_safe_task.py').write_bytes(base64.b64decode(''))
Path('/kaggle/working/apply_unified_configs.py').write_bytes(base64.b64decode(''))
Path('/kaggle/working/apply_source_fixes.py').write_bytes(base64.b64decode(''))
PYTOOLS
rm -rf "$PROGRESS_BASE"; mkdir -p "$PROGRESS_BASE"
python - <<'PYRESTORE'
import json, os, shutil, zipfile
from pathlib import Path
packid='PACK_D04U_DENSE'; base=Path(os.environ['PROGRESS_BASE']); inp=Path('/kaggle/input')
# Prefer the newest packed result ZIP.
zs=list(inp.rglob(f'{packid}_results.zip')) if inp.exists() else []
if zs:
    z=max(zs,key=lambda p:p.stat().st_mtime); tmp=Path('/kaggle/working')/f'_restore_{packid}'; shutil.rmtree(tmp,ignore_errors=True); tmp.mkdir()
    zipfile.ZipFile(z).extractall(tmp)
    found=list(tmp.rglob(f'packed_progress_{packid}'))
    if len(found)==1:
        shutil.rmtree(base,ignore_errors=True); shutil.move(str(found[0]),str(base)); print('RESTORED_PACKED',z)
    shutil.rmtree(tmp,ignore_errors=True)
# Also import previous per-method result ZIPs when present.
legacy={"ssf": "D04U_ssf", "conv_adapter": "D04U_conv_adapter", "bam": "D04U_bam", "residual_adapter": "D04U_residual_adapter"}
for method,oldid in legacy.items():
    dst=base/method
    if (dst/'TASK_SPEC.json').is_file(): continue
    cand=list(inp.rglob(f'{oldid}_results.zip')) if inp.exists() else []
    if not cand: continue
    z=max(cand,key=lambda p:p.stat().st_mtime); tmp=Path('/kaggle/working')/f'_restore_{oldid}'; shutil.rmtree(tmp,ignore_errors=True); tmp.mkdir()
    zipfile.ZipFile(z).extractall(tmp); found=list(tmp.rglob(f'progress_{oldid}'))
    if len(found)==1:
        shutil.rmtree(dst,ignore_errors=True); shutil.move(str(found[0]),str(dst)); print('IMPORTED_LEGACY',method,z)
    shutil.rmtree(tmp,ignore_errors=True)
PYRESTORE
mkdir -p "$DATA_ROOT" "$PROGRESS_BASE"
python - <<'PYGPU'
import torch
assert torch.cuda.is_available(),'Enable Kaggle GPU accelerator.'
print('GPU count=',torch.cuda.device_count()); [print(i,torch.cuda.get_device_name(i)) for i in range(torch.cuda.device_count())]
PYGPU
python /kaggle/working/apply_source_fixes.py
CONFIG_PATH="$REPO_DIR/configs/dense/experiments/binary_vit_pennfudan.yaml"
python /kaggle/working/apply_unified_configs.py --family dense "$CONFIG_PATH"
METHODS=(ssf conv_adapter bam residual_adapter)
for METHOD in "${METHODS[@]}"; do
  PROGRESS_ROOT="$PROGRESS_BASE/$METHOD"; mkdir -p "$PROGRESS_ROOT"
  COMPLETE=$(python - <<PYCHK
import json
from pathlib import Path
p=Path(r"$PROGRESS_ROOT")/"TASK_STATUS.json"
print("1" if p.is_file() and json.loads(p.read_text()).get("complete") else "0")
PYCHK
)
  if [[ "$COMPLETE" == "1" ]]; then echo "SKIP_COMPLETE $METHOD"; continue; fi
  NOW=$(date +%s); ELAPSED=$((NOW-SESSION_START_EPOCH)); HARD_LEFT=$((12*3600-ELAPSED)); if (( HARD_LEFT < 3600 )); then echo "STOP_PACK: less than 60 min remains before Kaggle 12h limit"; break; fi
  set +e
  python /kaggle/working/dense_safe_task.py --repo-root "$REPO_DIR" --config "$CONFIG_PATH" --method "$METHOD" --data-path "$DATA_ROOT" --progress-root "$PROGRESS_ROOT" --safe-minutes "$SAFE_MINUTES" --session-start-epoch "$SESSION_START_EPOCH" --safety-factor "$SAFETY_FACTOR" --reserve-minutes "$RESERVE_MINUTES" --max-gpus 2
  RC=$?; set -e
  pack_results
  if (( RC != 0 )); then echo "STOP_PACK: planner refused next full dense seed before launch; resume next session."; break; fi
  COMPLETE=$(python - <<PYCHK
import json
from pathlib import Path
p=Path(r"$PROGRESS_ROOT")/"TASK_STATUS.json"
print("1" if p.is_file() and json.loads(p.read_text()).get("complete") else "0")
PYCHK
)
  if [[ "$COMPLETE" != "1" ]]; then echo "STOP_PACK: current method incomplete after using remaining safe budget; resume next session."; break; fi
done
python - <<'PYSTATUS'
import json,os,time
from pathlib import Path
base=Path(os.environ['PROGRESS_BASE']); methods=['ssf', 'conv_adapter', 'bam', 'residual_adapter']
st={}
for m in methods:
 p=base/m/'TASK_STATUS.json'; d=json.loads(p.read_text()) if p.is_file() else {}; st[m]=bool(d.get('complete'))
out={'pack_id':os.environ['PACK_ID'],'complete':all(st.values()),'methods':st,'session_elapsed_minutes':(time.time()-float(os.environ['SESSION_START_EPOCH']))/60,'policy':'pack as many methods as safely fit; split only when next measured full seed does not fit'}
(base/'PACK_STATUS.json').write_text(json.dumps(out,indent=2)+'\n'); print(json.dumps(out,indent=2))
PYSTATUS
pack_results; trap - EXIT
echo "Upload ${PACK_ID}_results.zip only if incomplete, then rerun this same packed script."
